sequence.script:

var customer = mc.getPayloadJSON();
var customerId = customer.customerId;
  var customerName = customer.customerName;
    var connectionType = customer.connectionType;
      var previousBalance = Number(customer.previousBalance);
      var readings = customer.readings;
      var totalConsumption = 0;
      var totalEnergyCharge = 0;
      var  lowMonths = 0;
      var normalMonths = 0;
      var highMonths = 0;
      var criticalMonths = 0;
       for (var i = 0; i < readings.length; i++){
       totalConsumption += Number(readings[i].consumption);
       totalEnergyCharge += Number(readings[i].energyCharge);
       if(readings[i].usageStatus == "LOW"){
      lowMonths++;
       }
       else if (readings[i].usageStatus == "NORMAL"){
       normalMonths++;
       }
       else if (readings[i].usageStatus == "HIGH"){
       highMonths++;
       }
       else if (readings[i].usageStatus == "CRITICAL"){
       criticalMonths++;
       }
       }
       var risklevel;
       if(criticalMonths > 0 || highMonths >= 2 || previousBalance > 5000)
       {
       risklevel = "HIGH_RISK";
       }
       else if(highMonths == 1){
        risklevel = "MEDIUM_RISK";
       }
       else
       {
        risklevel = "LOW_RISK";
       }
       mc.setProperty("totalConsumption",totalConsumption);
       mc.setProperty("totalEnergyCharge",totalEnergyCharge);
     mc.setProperty("risklevel",risklevel);
